result.content:
1. ---
2. import SeriesBadge from './SeriesBadge.astro';
3. import { getSeriesMeta } from '../lib/series';
4. import { formatDateRange, isPlaceholderTime, countryFlag, isPastEvent } from '../lib/time';
5. import { SESSION_ABBR, isRaceType } from '../lib/sessions';
6. import broadcastData from '../../data/gold/broadcasts.json';
7. 
8. const hasBroadcast = (seriesId: string) => !!(broadcastData as any).series?.[seriesId];
9. 
10. interface Props {
11.   event: {
12.     id: string;
13.     seriesId: string;
14.     eventName: string;
15.     round: number;
16.     circuit: {
17.       name: string;
18.       city: string;
19.       country: string;
20.       countryCode: string;
21.     };
22.     sessions: { type: string; startTimeUTC: string }[];
23.     dateStart: string;
24.     dateEnd: string;
25.   };
26.   highlight?: boolean;
27. }
28. 
29. const { event, highlight = false } = Astro.props;
30. const meta = getSeriesMeta(event.seriesId);
31. const validSessions = event.sessions.filter(s => !isPlaceholderTime(s.startTimeUTC));
32. const past = isPastEvent(event.dateEnd, event.sessions);
33. const flag = countryFlag(event.circuit.countryCode);
34. 
35. function abbr(type: string) { return SESSION_ABBR[type] ?? type; }
36. 
37. function sessionDayKeyUTC(utc: string) {
38.   const date = new Date(utc);
39.   return `${date.getUTCFullYear()}-${date.getUTCMonth()}-${date.getUTCDate()}`;
40. }
41. 
42. function sessionDayLabelUTC(utc: string) {
43.   return new Intl.DateTimeFormat('en-US', {
44.     weekday: 'short',
45.     timeZone: 'UTC',
46.   }).format(new Date(utc));
47. }
48. 
49. const sessionGroups = validSessions.reduce<{ dayKey: string; dayLabel: string; sessions: typeof validSessions }[]>((groups, session) => {
50.   const dayKey = sessionDayKeyUTC(session.startTimeUTC);
51.   const existing = groups.at(-1);
52.   if (existing && existing.dayKey === dayKey) {
53.     existing.sessions.push(session);
54.     return groups;
55.   }
56. 
57.   groups.push({
58.     dayKey,
59.     dayLabel: sessionDayLabelUTC(session.startTimeUTC),
60.     sessions: [session],
61.   });
62.   return groups;
63. }, []);
64. 
65. // Find next session that hasn't started yet (for "next session" chip)
66. const nextSession = validSessions.find(s => new Date(s.startTimeUTC) > new Date());
67. ---
68. 
69. <article
70.   class:list={[
71.     'group relative rounded-xl border transition-all duration-200 cursor-pointer select-none',
72.     past
73.       ? 'border-zinc-800/40 bg-zinc-900/20 opacity-40 hover:opacity-60'
74.       : highlight
75.         ? 'border-zinc-500/60 bg-zinc-900 shadow-lg shadow-black/40'
76.         : 'border-zinc-800 bg-zinc-900 hover:border-zinc-700',
77.   ]}
78.   data-event-id={event.id}
79.   role="button"
80.   tabindex="0"
81.   aria-label={`View details for ${event.eventName}`}
82. >
83.   {/* Left accent bar in series color */}
84.   {!past && (
85.     <div
86.       class="absolute left-0 top-3 bottom-3 w-0.5 rounded-full"
87.       style={`background-color: ${meta.color};`}
88.     />
89.   )}
90. 
91.   <div class="px-5 py-4">
92.     {/* Top row: badge + round + date + fav */}
93.     <div class="flex items-start justify-between gap-3 mb-2">
94.       <div class="flex items-center gap-2 flex-wrap min-w-0">
95.         <SeriesBadge seriesId={event.seriesId} />
96.         <span class="text-[11px] text-zinc-500 font-mono tracking-tight">Rd {event.round}</span>
97.         {past && (
98.           <span class="text-[10px] px-1.5 py-0.5 rounded-full bg-zinc-800 text-zinc-600 font-semibold uppercase tracking-widest">
99.             Done
100.           </span>
101.         )}
102.         {highlight && !past && (
103.           <span
104.             class="text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest animate-pulse"
105.             style={`background-color: ${meta.color}25; color: ${meta.color};`}
106.           >
107.             Next up
108.           </span>
109.         )}
110.       </div>
111.       <div class="flex items-center gap-2 shrink-0">
112.         <span class="text-sm font-medium text-zinc-400 tabular-nums">
113.           {formatDateRange(event.dateStart, event.dateEnd)}
114.         </span>
115.         {/* Favorite button */}
116.         <button
117.           class="fav-btn ml-1 p-1 rounded-full hover:bg-zinc-800 transition-colors"
118.           data-fav="false"
119.           data-fav-id={event.id}
120.           aria-label="Add to favorites"
121.         >
122.           <svg class="w-4 h-4 stroke-zinc-600 fill-none" viewBox="0 0 24 24" stroke-width="2">
123.             <path stroke-linecap="round" stroke-linejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z" />
124.           </svg>
125.         </button>
126.       </div>
127.     </div>
128. 
129.     {/* Event name */}
130.     <h3 class:list={[
131.       'font-bold leading-tight mb-2 text-base',
132.       past ? 'text-zinc-500' : 'text-zinc-100',
133.     ]}>
134.       {event.eventName}
135.     </h3>
136. 
137.     {/* Circuit */}
138.     <div class="flex items-center gap-1.5 text-sm text-zinc-500 mb-3">
139.       {flag && <span class="text-base leading-none">{flag}</span>}
140.       <span class="text-zinc-400">{event.circuit.name}</span>
141.       {event.circuit.city && <span class="text-zinc-700">·</span>}
142.       {event.circuit.city && <span>{event.circuit.city}</span>}
