207.   function initCards() {
208.     // ── Local time conversion + today indicators ──
209.     const _now = new Date();
210.     document.querySelectorAll<HTMLTimeElement>('[data-local-time][data-format="time-short"]').forEach(el => {
211.       el.textContent = formatLocalValue(el.dataset.localTime!, 'time-short');
212. 
213.       const d = new Date(el.dataset.localTime!);
214.       const isTodaySession =
215.         d.getFullYear() === _now.getFullYear() &&
216.         d.getMonth()    === _now.getMonth()    &&
217.         d.getDate()     === _now.getDate()     &&
218.         d > _now; // only upcoming sessions today (live already has its own badge)
219. 
220.       const sessionRow = el.parentElement;
221.       if (isTodaySession && sessionRow && !sessionRow.querySelector('.today-dot')) {
222.         const badge = document.createElement('span');
223.         badge.className = 'today-dot text-[9px] font-bold uppercase tracking-wide text-amber-400 border border-amber-400/40 px-1 rounded leading-none py-px shrink-0';
224.         badge.textContent = 'today';
225.         sessionRow.appendChild(badge);
226.       }
227.     });
228. 
229.     document.querySelectorAll<HTMLElement>('[data-session-strip]').forEach(strip => {
230.       const rows = Array.from(strip.querySelectorAll<HTMLElement>('[data-session-row]'));
231.       if (rows.length === 0) return;
232. 
233.       const groups = new Map<string, { label: string; rows: HTMLElement[] }>();
234.       rows.forEach(row => {
235.         const utc = row.dataset.sessionUtc;
236.         if (!utc) return;
237. 
238.         const localDate = new Date(utc);
239.         const localDayKey = `${localDate.getFullYear()}-${localDate.getMonth()}-${localDate.getDate()}`;
240.         const localDayLabel = new Intl.DateTimeFormat(undefined, { weekday: 'short' }).format(localDate);
241.         const existing = groups.get(localDayKey);
242. 
243.         if (existing) {
244.           existing.rows.push(row);
245.           return;
246.         }
247. 
248.         groups.set(localDayKey, { label: localDayLabel, rows: [row] });
249.       });
250. 
251.       strip.replaceChildren();
252. 
253.       groups.forEach(group => {
254.         const wrapper = document.createElement('div');
255.         wrapper.className = 'session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950/40 px-2.5 py-1.5';
256.         wrapper.dataset.sessionGroup = '';
257. 
258.         const chip = document.createElement('span');
259.         chip.className = 'session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800/80 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0';
260.         chip.dataset.sessionDay = '';
261.         chip.textContent = group.label;
262.         wrapper.appendChild(chip);
263. 
264.         const inner = document.createElement('div');
265.         inner.className = 'flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0';
266.         group.rows.forEach(row => inner.appendChild(row));
267.         wrapper.appendChild(inner);
268. 
269.         strip.appendChild(wrapper);
270.       });
271.     });
272. 
273.     // ── Live session indicators ──
274.     document.querySelectorAll<HTMLElement>('[data-event-id]').forEach(card => {
275.       const eventId = card.dataset.eventId;
276.       if (!eventId) return;
277. 
278.       const ev = getRegisteredEvent(eventId);
279.       const live = ev ? getLiveSession(ev.sessions ?? []) : null;
280.       const existing = card.querySelector('.live-badge');
281.       if (existing) existing.remove();
282.       if (live) {
283.         const badge = document.createElement('span');
284.         badge.className = 'live-badge live-pulse inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest bg-emerald-500/20 text-emerald-400';
285.         badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block"></span>Live';
286.         const wrap = card.querySelector('.flex.items-center.gap-2.flex-wrap');
287.         if (wrap) wrap.appendChild(badge);
288.       }
289.     });
290. 
291.     // ── Favorites ──
292.     document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
293.       const id = btn.dataset.favId!;
294.       if (!id) return; // skip buttons without a valid id
295.       btn.dataset.fav = readFavorites().includes(id) ? 'true' : 'false';
296.       if (btn.dataset.favBound === 'true') return;
297.       btn.dataset.favBound = 'true';
298.       btn.addEventListener('click', (e) => {
299.         e.stopPropagation();
300.         btn.dataset.fav = toggleFavorite(id) ? 'true' : 'false';
301.       });
302.     });
303. 
304.     // Sync fav button states when another tab/page changes them
305.     function onFavsChanged() {
306.       const favs = new Set(readFavorites());
307.       document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
308.         const id = btn.dataset.favId;
309.         if (id) btn.dataset.fav = favs.has(id) ? 'true' : 'false';
310.       });
311.     }
312.     if (!window.__rt) window.__rt = {};
313.     if (window.__rt.favsHandler) window.removeEventListener('rt-favs-changed', window.__rt.favsHandler);
314.     window.__rt.favsHandler = onFavsChanged;
315.     window.addEventListener('rt-favs-changed', onFavsChanged);
316. 
317.     bindEventOpeners();
318.   }
319. 
320.   initCards();
321.   document.addEventListener('astro:after-swap', initCards);
322.   window.addEventListener(RT_EVENTS_REGISTERED, initCards);
323. </script>
