 <script>
   import { formatLocalValue, getLiveSession, readFavorites, toggleFavorite } from '../lib/client-utils';
   import { bindEventOpeners, getRegisteredEvent, RT_EVENTS_REGISTERED } from '../lib/event-client';

   function initCards() {
     // ── Local time conversion + today indicators ──
     const _now = new Date();
     document.querySelectorAll<HTMLTimeElement>('[data-local-time][data-format="time-short"]').forEach(el => {
       el.textContent = formatLocalValue(el.dataset.localTime!, 'time-short');

       const d = new Date(el.dataset.localTime!);
       const isTodaySession =
         d.getFullYear() === _now.getFullYear() &&
         d.getMonth()    === _now.getMonth()    &&
         d.getDate()     === _now.getDate()     &&
         d > _now; // only upcoming sessions today (live already has its own badge)

       const sessionRow = el.parentElement;
       if (isTodaySession && sessionRow && !sessionRow.querySelector('.today-dot')) {
         const badge = document.createElement('span');
         badge.className = 'today-dot text-[9px] font-bold uppercase tracking-wide text-amber-400 border border-amber-400/40 px-1 rounded leading-none py-px shrink-0';
         badge.textContent = 'today';
         sessionRow.appendChild(badge);
       }
     });

     document.querySelectorAll<HTMLElement>('[data-session-strip]').forEach(strip => {
       const rows = Array.from(strip.querySelectorAll<HTMLElement>('[data-session-row]'));
       if (rows.length === 0) return;

       const groups = new Map<string, { label: string; rows: HTMLElement[] }>();
       rows.forEach(row => {
         const utc = row.dataset.sessionUtc;
         if (!utc) return;

         const localDate = new Date(utc);
         const localDayKey = `${localDate.getFullYear()}-${localDate.getMonth()}-${localDate.getDate()}`;
         const localDayLabel = new Intl.DateTimeFormat(undefined, { weekday: 'short' }).format(localDate);
         const existing = groups.get(localDayKey);

         if (existing) {
           existing.rows.push(row);
           return;
         }

         groups.set(localDayKey, { label: localDayLabel, rows: [row] });
       });

       strip.replaceChildren();

       groups.forEach(group => {
         const wrapper = document.createElement('div');
         wrapper.className = 'session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950/40 px-2.5 py-1.5';
         wrapper.dataset.sessionGroup = '';

         const chip = document.createElement('span');
         chip.className = 'session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800/80 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0';
         chip.dataset.sessionDay = '';
         chip.textContent = group.label;
         wrapper.appendChild(chip);

         const inner = document.createElement('div');
         inner.className = 'flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0';
         group.rows.forEach(row => inner.appendChild(row));
         wrapper.appendChild(inner);

         strip.appendChild(wrapper);
       });
     });

     // ── Live session indicators ──
     document.querySelectorAll<HTMLElement>('[data-event-id]').forEach(card => {
       const eventId = card.dataset.eventId;
       if (!eventId) return;

       const ev = getRegisteredEvent(eventId);
       const live = ev ? getLiveSession(ev.sessions ?? []) : null;
       const existing = card.querySelector('.live-badge');
       if (existing) existing.remove();
       if (live) {
         const badge = document.createElement('span');
         badge.className = 'live-badge live-pulse inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest bg-emerald-500/20 text-emerald-400';
         badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block"></span>Live';
         const wrap = card.querySelector('.flex.items-center.gap-2.flex-wrap');
         if (wrap) wrap.appendChild(badge);
       }
     });

     // ── Favorites ──
     document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
       const id = btn.dataset.favId!;
       if (!id) return; // skip buttons without a valid id
       btn.dataset.fav = readFavorites().includes(id) ? 'true' : 'false';
       if (btn.dataset.favBound === 'true') return;
       btn.dataset.favBound = 'true';
       btn.addEventListener('click', (e) => {
         e.stopPropagation();
         btn.dataset.fav = toggleFavorite(id) ? 'true' : 'false';
       });
     });

     // Sync fav button states when another tab/page changes them
     function onFavsChanged() {
       const favs = new Set(readFavorites());
       document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
         const id = btn.dataset.favId;
         if (id) btn.dataset.fav = favs.has(id) ? 'true' : 'false';
       });
     }
     if (!window.__rt) window.__rt = {};
     if (window.__rt.favsHandler) window.removeEventListener('rt-favs-changed', window.__rt.favsHandler);
     window.__rt.favsHandler = onFavsChanged;
     window.addEventListener('rt-favs-changed', onFavsChanged);

     bindEventOpeners();
   }

   initCards();
   document.addEventListener('astro:after-swap', initCards);
   window.addEventListener(RT_EVENTS_REGISTERED, initCards);
 </script>

