           >
             <span
               class="session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0"
