                       style={isRaceType(session.type) ? `background-color: ${meta.color}` : isNext ? 'background-color: #a1a1aa' : 'background-color: #3f3f46'}
                     />
                     <span class:list={['font-semibold', isRaceType(session.type) ? 'text-zinc-100' : isNext ? 'text-zinc-300' : 'text-zinc-500']}>
                       {abbr(session.type)}
                     </span>
                     <time
                       class="tabular-nums text-zinc-600"
                       datetime={session.startTimeUTC}
                       data-local-time={session.startTimeUTC}
                       data-format="time-short"
