 <article
   class:list={[
     'group relative rounded-xl border transition-all duration-200 cursor-pointer select-none',
     past
       ? 'border-zinc-800/40 bg-zinc-900/20 opacity-40 hover:opacity-60'
       : highlight
         ? 'border-zinc-500/60 bg-zinc-900 shadow-lg shadow-black/40'
         : 'border-zinc-800 bg-zinc-900 hover:border-zinc-700',
   ]}
   data-event-id={event.id}
   role="button"
   tabindex="0"
   aria-label={`View details for ${event.eventName}`}
 >
   {/* Left accent bar in series color */}
   {!past && (
     <div
       class="absolute left-0 top-3 bottom-3 w-0.5 rounded-full"
       style={`background-color: ${meta.color};`}
     />
   )}

   <div class="px-5 py-4">
     {/* Top row: badge + round + date + fav */}
     <div class="flex items-start justify-between gap-3 mb-2">
       <div class="flex items-center gap-2 flex-wrap min-w-0">
         <SeriesBadge seriesId={event.seriesId} />
         <span class="text-[11px] text-zinc-500 font-mono tracking-tight">Rd {event.round}</span>
         {past && (
           <span class="text-[10px] px-1.5 py-0.5 rounded-full bg-zinc-800 text-zinc-600 font-semibold uppercase tracking-widest">
             Done
           </span>
         )}
         {highlight && !past && (
           <span
             class="text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest animate-pulse"
             style={`background-color: ${meta.color}25; color: ${meta.color};`}
           >
             Next up
           </span>
         )}
       </div>
       <div class="flex items-center gap-2 shrink-0">
         <span class="text-sm font-medium text-zinc-400 tabular-nums">
           {formatDateRange(event.dateStart, event.dateEnd)}
         </span>
         {/* Favorite button */}
         <button
           class="fav-btn ml-1 p-1 rounded-full hover:bg-zinc-800 transition-colors"
           data-fav="false"
           data-fav-id={event.id}
           aria-label="Add to favorites"
         >
           <svg class="w-4 h-4 stroke-zinc-600 fill-none" viewBox="0 0 24 24" stroke-width="2">
             <path stroke-linecap="round" stroke-linejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z" />
           </svg>
         </button>
       </div>
     </div>

     {/* Event name */}
     <h3 class:list={[
       'font-bold leading-tight mb-2 text-base',
       past ? 'text-zinc-500' : 'text-zinc-100',
     ]}>
       {event.eventName}
     </h3>

     {/* Circuit */}
     <div class="flex items-center gap-1.5 text-sm text-zinc-500 mb-3">
       {flag && <span class="text-base leading-none">{flag}</span>}
       <span class="text-zinc-400">{event.circuit.name}</span>
       {event.circuit.city && <span class="text-zinc-700">·</span>}
       {event.circuit.city && <span>{event.circuit.city}</span>}
       {hasBroadcast(event.seriesId) && (
         <svg class="w-3.5 h-3.5 text-zinc-600 ml-auto shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" aria-label="Broadcast info available">
           <path stroke-linecap="round" stroke-linejoin="round" d="M6 20.25h12m-7.5-3v3m3-3v3m-10.125-3h17.25c.621 0 1.125-.504 1.125-1.125V4.875c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v11.25c0 .621.504 1.125 1.125 1.125Z" />
         </svg>
       )}
     </div>

     {/* Sessions row */}
     {validSessions.length > 0 && (
       <div class="flex flex-wrap gap-2.5 pt-2 border-t border-zinc-800/60" data-session-strip>
         {sessionGroups.map(group => (
           <div
             class="session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950 px-2.5 py-1.5"
             data-session-group
             data-session-day-key={group.dayKey}
           >
             <span
               class="session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0"
               data-session-day
             >
               {group.dayLabel}
             </span>

             <div class="flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0">
               {group.sessions.map(session => {
                 const isNext = nextSession?.startTimeUTC === session.startTimeUTC;
                 return (
                   <div
                     class:list={['flex items-center gap-1.5 text-xs', isNext ? 'text-zinc-200' : '']}
                     data-session-row
                     data-session-utc={session.startTimeUTC}
                   >
                     <span
                       class="w-1.5 h-1.5 rounded-full shrink-0"
                       style={isRaceType(session.type) ? `background-color: ${meta.color}` : isNext ? 'background-color: #a1a1aa' : 'background-color: #3f3f46'}
                     />
                     <span class:list={['font-semibold', isRaceType(session.type) ? 'text-zinc-100' : isNext ? 'text-zinc-300' : 'text-zinc-500']}>
                       {abbr(session.type)}
                     </span>
                     <time
                       class="tabular-nums text-zinc-600"
                       datetime={session.startTimeUTC}
                       data-local-time={session.startTimeUTC}
                       data-format="time-short"
                     >
                       {new Date(session.startTimeUTC).toLocaleTimeString('en', {
                         hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'UTC',
                       })}
                     </time>
                   </div>
                 );
               })}
             </div>
           </div>
         ))}
       </div>
     )}
   </div>
 </article>

 <script>
   import { formatLocalValue, getLiveSession, readFavorites, toggleFavorite } from '../lib/client-utils';
   import { bindEventOpeners, getRegisteredEvent, RT_EVENTS_REGISTERED } from '../lib/event-client';

   function initCards() {
     // ── Local time conversion + today indicators ──
     const _now = new Date();
     document.querySelectorAll<HTMLTimeElement>('[data-local-time][data-format="time-short"]').forEach(el => {
       el.textContent = formatLocalValue(el.dataset.localTime!, 'time-short');

       const d = new Date(el.dataset.localTime!);
       const isTodaySession =
         d.getFullYear() === _now.getFullYear() &&
         d.getMonth()    === _now.getMonth()    &&
         d.getDate()     === _now.getDate()     &&
         d > _now; // only upcoming sessions today (live already has its own badge)

       const sessionRow = el.parentElement;
       if (isTodaySession && sessionRow && !sessionRow.querySelector('.today-dot')) {
         const badge = document.createElement('span');
         badge.className = 'today-dot text-[9px] font-bold uppercase tracking-wide text-amber-400 border border-amber-400/40 px-1 rounded leading-none py-px shrink-0';
         badge.textContent = 'today';
         sessionRow.appendChild(badge);
       }
     });

     document.querySelectorAll<HTMLElement>('[data-session-strip]').forEach(strip => {
       const rows = Array.from(strip.querySelectorAll<HTMLElement>('[data-session-row]'));
       if (rows.length === 0) return;

       const groups = new Map<string, { label: string; rows: HTMLElement[] }>();
       rows.forEach(row => {
         const utc = row.dataset.sessionUtc;
         if (!utc) return;

         const localDate = new Date(utc);
         const localDayKey = `${localDate.getFullYear()}-${localDate.getMonth()}-${localDate.getDate()}`;
         const localDayLabel = new Intl.DateTimeFormat(undefined, { weekday: 'short' }).format(localDate);
         const existing = groups.get(localDayKey);

         if (existing) {
           existing.rows.push(row);
           return;
         }

         groups.set(localDayKey, { label: localDayLabel, rows: [row] });
       });

       strip.replaceChildren();

       groups.forEach(group => {
         const wrapper = document.createElement('div');
         wrapper.className = 'session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950/40 px-2.5 py-1.5';
         wrapper.dataset.sessionGroup = '';

         const chip = document.createElement('span');
         chip.className = 'session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800/80 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0';
         chip.dataset.sessionDay = '';
         chip.textContent = group.label;
         wrapper.appendChild(chip);

         const inner = document.createElement('div');
         inner.className = 'flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0';
         group.rows.forEach(row => inner.appendChild(row));
         wrapper.appendChild(inner);

         strip.appendChild(wrapper);
       });
     });

     // ── Live session indicators ──
     document.querySelectorAll<HTMLElement>('[data-event-id]').forEach(card => {
       const eventId = card.dataset.eventId;
       if (!eventId) return;

       const ev = getRegisteredEvent(eventId);
       const live = ev ? getLiveSession(ev.sessions ?? []) : null;
       const existing = card.querySelector('.live-badge');
       if (existing) existing.remove();
       if (live) {
         const badge = document.createElement('span');
         badge.className = 'live-badge live-pulse inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest bg-emerald-500/20 text-emerald-400';
         badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block"></span>Live';
         const wrap = card.querySelector('.flex.items-center.gap-2.flex-wrap');
         if (wrap) wrap.appendChild(badge);
       }
     });

     // ── Favorites ──
     document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
       const id = btn.dataset.favId!;
       if (!id) return; // skip buttons without a valid id
       btn.dataset.fav = readFavorites().includes(id) ? 'true' : 'false';
       if (btn.dataset.favBound === 'true') return;
       btn.dataset.favBound = 'true';
       btn.addEventListener('click', (e) => {
         e.stopPropagation();
         btn.dataset.fav = toggleFavorite(id) ? 'true' : 'false';
       });
     });

     // Sync fav button states when another tab/page changes them
     function onFavsChanged() {
       const favs = new Set(readFavorites());
       document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
         const id = btn.dataset.favId;
         if (id) btn.dataset.fav = favs.has(id) ? 'true' : 'false';
       });
     }
     if (!window.__rt) window.__rt = {};
     if (window.__rt.favsHandler) window.removeEventListener('rt-favs-changed', window.__rt.favsHandler);
     window.__rt.favsHandler = onFavsChanged;
     window.addEventListener('rt-favs-changed', onFavsChanged);

     bindEventOpeners();
   }

   initCards();
   document.addEventListener('astro:after-swap', initCards);
   window.addEventListener(RT_EVENTS_REGISTERED, initCards);
 </script>

