74.       : highlight
75.         ? 'border-zinc-500/60 bg-zinc-900 shadow-lg shadow-black/40'
76.         : 'border-zinc-800 bg-zinc-900 hover:border-zinc-700',
77.   ]}
78.   data-event-id={event.id}
79.   role="button"
80.   tabindex="0"
81.   aria-label={`View details for ${event.eventName}`}
82. >
83.   {/* Left accent bar in series color */}
84.   {!past && (
85.     <div
86.       class="absolute left-0 top-3 bottom-3 w-0.5 rounded-full"
87.       style={`background-color: ${meta.color};`}
88.     />
89.   )}
90. 
91.   <div class="px-5 py-4">
92.     {/* Top row: badge + round + date + fav */}
93.     <div class="flex items-start justify-between gap-3 mb-2">
94.       <div class="flex items-center gap-2 flex-wrap min-w-0">
95.         <SeriesBadge seriesId={event.seriesId} />
96.         <span class="text-[11px] text-zinc-500 font-mono tracking-tight">Rd {event.round}</span>
97.         {past && (
98.           <span class="text-[10px] px-1.5 py-0.5 rounded-full bg-zinc-800 text-zinc-600 font-semibold uppercase tracking-widest">
99.             Done
100.           </span>
101.         )}
102.         {highlight && !past && (
103.           <span
104.             class="text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest animate-pulse"
105.             style={`background-color: ${meta.color}25; color: ${meta.color};`}
106.           >
107.             Next up
108.           </span>
109.         )}
110.       </div>
111.       <div class="flex items-center gap-2 shrink-0">
112.         <span class="text-sm font-medium text-zinc-400 tabular-nums">
113.           {formatDateRange(event.dateStart, event.dateEnd)}
114.         </span>
115.         {/* Favorite button */}
116.         <button
117.           class="fav-btn ml-1 p-1 rounded-full hover:bg-zinc-800 transition-colors"
118.           data-fav="false"
119.           data-fav-id={event.id}
120.           aria-label="Add to favorites"
121.         >
122.           <svg class="w-4 h-4 stroke-zinc-600 fill-none" viewBox="0 0 24 24" stroke-width="2">
123.             <path stroke-linecap="round" stroke-linejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12Z" />
124.           </svg>
125.         </button>
126.       </div>
127.     </div>
128. 
129.     {/* Event name */}
130.     <h3 class:list={[
131.       'font-bold leading-tight mb-2 text-base',
132.       past ? 'text-zinc-500' : 'text-zinc-100',
133.     ]}>
134.       {event.eventName}
135.     </h3>
136. 
137.     {/* Circuit */}
138.     <div class="flex items-center gap-1.5 text-sm text-zinc-500 mb-3">
139.       {flag && <span class="text-base leading-none">{flag}</span>}
140.       <span class="text-zinc-400">{event.circuit.name}</span>
141.       {event.circuit.city && <span class="text-zinc-700">·</span>}
142.       {event.circuit.city && <span>{event.circuit.city}</span>}
143.       {hasBroadcast(event.seriesId) && (
144.         <svg class="w-3.5 h-3.5 text-zinc-600 ml-auto shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" aria-label="Broadcast info available">
145.           <path stroke-linecap="round" stroke-linejoin="round" d="M6 20.25h12m-7.5-3v3m3-3v3m-10.125-3h17.25c.621 0 1.125-.504 1.125-1.125V4.875c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v11.25c0 .621.504 1.125 1.125 1.125Z" />
146.         </svg>
147.       )}
148.     </div>
149. 
150.     {/* Sessions row */}
151.     {validSessions.length > 0 && (
152.       <div class="flex flex-wrap gap-2.5 pt-2 border-t border-zinc-800/60" data-session-strip>
153.         {sessionGroups.map(group => (
154.           <div
155.             class="session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950 px-2.5 py-1.5"
156.             data-session-group
157.             data-session-day-key={group.dayKey}
158.           >
159.             <span
160.               class="session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0"
161.               data-session-day
162.             >
163.               {group.dayLabel}
164.             </span>
165. 
166.             <div class="flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0">
167.               {group.sessions.map(session => {
168.                 const isNext = nextSession?.startTimeUTC === session.startTimeUTC;
169.                 return (
170.                   <div
171.                     class:list={['flex items-center gap-1.5 text-xs', isNext ? 'text-zinc-200' : '']}
172.                     data-session-row
173.                     data-session-utc={session.startTimeUTC}
174.                   >
175.                     <span
176.                       class="w-1.5 h-1.5 rounded-full shrink-0"
177.                       style={isRaceType(session.type) ? `background-color: ${meta.color}` : isNext ? 'background-color: #a1a1aa' : 'background-color: #3f3f46'}
178.                     />
179.                     <span class:list={['font-semibold', isRaceType(session.type) ? 'text-zinc-100' : isNext ? 'text-zinc-300' : 'text-zinc-500']}>
180.                       {abbr(session.type)}
181.                     </span>
182.                     <time
183.                       class="tabular-nums text-zinc-600"
184.                       datetime={session.startTimeUTC}
185.                       data-local-time={session.startTimeUTC}
186.                       data-format="time-short"
187.                     >
188.                       {new Date(session.startTimeUTC).toLocaleTimeString('en', {
189.                         hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'UTC',
190.                       })}
191.                     </time>
192.                   </div>
193.                 );
194.               })}
195.             </div>
196.           </div>
197.         ))}
198.       </div>
199.     )}
200.   </div>
201. </article>
202. 
203. <script>
204.   import { formatLocalValue, getLiveSession, readFavorites, toggleFavorite } from '../lib/client-utils';
205.   import { bindEventOpeners, getRegisteredEvent, RT_EVENTS_REGISTERED } from '../lib/event-client';
206. 
207.   function initCards() {
208.     // ── Local time conversion + today indicators ──
209.     const _now = new Date();
210.     document.querySelectorAll<HTMLTimeElement>('[data-local-time][data-format="time-short"]').forEach(el => {
211.       el.textContent = formatLocalValue(el.dataset.localTime!, 'time-short');
212. 
213.       const d = new Date(el.dataset.localTime!);
214.       const isTodaySession =
215.         d.getFullYear() === _now.getFullYear() &&
216.         d.getMonth()    === _now.getMonth()    &&
217.         d.getDate()     === _now.getDate()     &&
218.         d > _now; // only upcoming sessions today (live already has its own badge)
219. 
220.       const sessionRow = el.parentElement;
221.       if (isTodaySession && sessionRow && !sessionRow.querySelector('.today-dot')) {
222.         const badge = document.createElement('span');
223.         badge.className = 'today-dot text-[9px] font-bold uppercase tracking-wide text-amber-400 border border-amber-400/40 px-1 rounded leading-none py-px shrink-0';
224.         badge.textContent = 'today';
225.         sessionRow.appendChild(badge);
226.       }
227.     });
228. 
229.     document.querySelectorAll<HTMLElement>('[data-session-strip]').forEach(strip => {
230.       const rows = Array.from(strip.querySelectorAll<HTMLElement>('[data-session-row]'));
231.       if (rows.length === 0) return;
232. 
233.       const groups = new Map<string, { label: string; rows: HTMLElement[] }>();
234.       rows.forEach(row => {
235.         const utc = row.dataset.sessionUtc;
236.         if (!utc) return;
237. 
238.         const localDate = new Date(utc);
239.         const localDayKey = `${localDate.getFullYear()}-${localDate.getMonth()}-${localDate.getDate()}`;
240.         const localDayLabel = new Intl.DateTimeFormat(undefined, { weekday: 'short' }).format(localDate);
241.         const existing = groups.get(localDayKey);
242. 
243.         if (existing) {
244.           existing.rows.push(row);
245.           return;
246.         }
247. 
248.         groups.set(localDayKey, { label: localDayLabel, rows: [row] });
249.       });
250. 
251.       strip.replaceChildren();
252. 
253.       groups.forEach(group => {
254.         const wrapper = document.createElement('div');
255.         wrapper.className = 'session-day-group inline-flex items-center gap-2 rounded-lg border border-zinc-800/80 bg-zinc-950/40 px-2.5 py-1.5';
256.         wrapper.dataset.sessionGroup = '';
257. 
258.         const chip = document.createElement('span');
259.         chip.className = 'session-day-chip inline-flex items-center rounded-full border border-zinc-700/70 bg-zinc-800/80 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-[0.14em] text-zinc-400 shrink-0';
260.         chip.dataset.sessionDay = '';
261.         chip.textContent = group.label;
262.         wrapper.appendChild(chip);
263. 
264.         const inner = document.createElement('div');
265.         inner.className = 'flex flex-wrap items-center gap-x-4 gap-y-1.5 min-w-0';
266.         group.rows.forEach(row => inner.appendChild(row));
267.         wrapper.appendChild(inner);
268. 
269.         strip.appendChild(wrapper);
270.       });
271.     });
272. 
273.     // ── Live session indicators ──
274.     document.querySelectorAll<HTMLElement>('[data-event-id]').forEach(card => {
275.       const eventId = card.dataset.eventId;
276.       if (!eventId) return;
277. 
278.       const ev = getRegisteredEvent(eventId);
279.       const live = ev ? getLiveSession(ev.sessions ?? []) : null;
280.       const existing = card.querySelector('.live-badge');
281.       if (existing) existing.remove();
282.       if (live) {
283.         const badge = document.createElement('span');
284.         badge.className = 'live-badge live-pulse inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase tracking-widest bg-emerald-500/20 text-emerald-400';
285.         badge.innerHTML = '<span class="w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block"></span>Live';
286.         const wrap = card.querySelector('.flex.items-center.gap-2.flex-wrap');
287.         if (wrap) wrap.appendChild(badge);
288.       }
289.     });
290. 
291.     // ── Favorites ──
292.     document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
293.       const id = btn.dataset.favId!;
294.       if (!id) return; // skip buttons without a valid id
295.       btn.dataset.fav = readFavorites().includes(id) ? 'true' : 'false';
296.       if (btn.dataset.favBound === 'true') return;
297.       btn.dataset.favBound = 'true';
298.       btn.addEventListener('click', (e) => {
299.         e.stopPropagation();
300.         btn.dataset.fav = toggleFavorite(id) ? 'true' : 'false';
301.       });
302.     });
303. 
304.     // Sync fav button states when another tab/page changes them
305.     function onFavsChanged() {
306.       const favs = new Set(readFavorites());
307.       document.querySelectorAll<HTMLButtonElement>('.fav-btn').forEach(btn => {
308.         const id = btn.dataset.favId;
309.         if (id) btn.dataset.fav = favs.has(id) ? 'true' : 'false';
310.       });
311.     }
312.     if (!window.__rt) window.__rt = {};
313.     if (window.__rt.favsHandler) window.removeEventListener('rt-favs-changed', window.__rt.favsHandler);
314.     window.__rt.favsHandler = onFavsChanged;
315.     window.addEventListener('rt-favs-changed', onFavsChanged);
316. 
317.     bindEventOpeners();
318.   }
319. 
320.   initCards();
321.   document.addEventListener('astro:after-swap', initCards);
322.   window.addEventListener(RT_EVENTS_REGISTERED, initCards);
323. </script>
324.

