 import SeriesBadge from './SeriesBadge.astro';
 import { getSeriesMeta } from '../lib/series';
 import { formatDateRange, isPlaceholderTime, countryFlag, isPastEvent } from '../lib/time';
 import { SESSION_ABBR, isRaceType } from '../lib/sessions';
 import broadcastData from '../../data/gold/broadcasts.json';

 const hasBroadcast = (seriesId: string) => !!(broadcastData as any).series?.[seriesId];

 interface Props {
   event: {
     id: string;
     seriesId: string;
     eventName: string;
     round: number;
     circuit: {
       name: string;
       city: string;
       country: string;
       countryCode: string;
     };
     sessions: { type: string; startTimeUTC: string }[];
     dateStart: string;
     dateEnd: string;
   };
   highlight?: boolean;
 }

 const { event, highlight = false } = Astro.props;
 const meta = getSeriesMeta(event.seriesId);
 const validSessions = event.sessions.filter(s => !isPlaceholderTime(s.startTimeUTC));
 const past = isPastEvent(event.dateEnd, event.sessions);
 const flag = countryFlag(event.circuit.countryCode);

 function abbr(type: string) { return SESSION_ABBR[type] ?? type; }

 function sessionDayKeyUTC(utc: string) {
   const date = new Date(utc);
   return `${date.getUTCFullYear()}-${date.getUTCMonth()}-${date.getUTCDate()}`;
 }

 function sessionDayLabelUTC(utc: string) {
   return new Intl.DateTimeFormat('en-US', {
     weekday: 'short',
     timeZone: 'UTC',
   }).format(new Date(utc));
 }

 const sessionGroups = validSessions.reduce<{ dayKey: string; dayLabel: string; sessions: typeof validSessions }[]>((groups, session) => {
   const dayKey = sessionDayKeyUTC(session.startTimeUTC);
   const existing = groups.at(-1);
   if (existing && existing.dayKey === dayKey) {
     existing.sessions.push(session);
     return groups;
   }

   groups.push({
     dayKey,
     dayLabel: sessionDayLabelUTC(session.startTimeUTC),
     sessions: [session],
   });
   return groups;
 }, []);

 // Find next session that hasn't started yet (for "next session" chip)
 const nextSession = validSessions.find(s => new Date(s.startTimeUTC) > new Date());
