28. 
29. function renderSessionsHtml(sessions: RaceSession[], accentColor: string, nonRaceTextClass: string): string {
30.   return sessions.map((session) => {
31.     const isRace = isRaceType(session.type);
32.     const label = SESSION_ABBR[session.type] ?? session.type;
33.     const time = formatLocalTime(session.startTimeUTC);
