38.       <span class="tabular-nums text-zinc-600">${escapeHtml(time)}</span>
39.     </div>`;
40.   }).join('');
41. }
42. 
43. function renderCalendarSpanLabel(event: RaceEvent, dateStr: string, accentColor: string): string {
44.   if (event.dateStart === event.dateEnd) return '';
45.   if (event.dateStart === dateStr) {
46.     return '<span class="text-[10px] text-zinc-600">Weekend starts</span>';
47.   }
48.   if (event.dateEnd === dateStr) {
49.     return `<span class="text-[10px] font-bold uppercase tracking-wider" style="color:${accentColor}">Race day</span>`;
50.   }
51.   return '<span class="text-[10px] text-zinc-600">Race weekend</span>';
52. }
53. 
54. export function renderClientEventCard(event: RaceEvent, options: RenderClientEventCardOptions): string {
55.   const meta = getSeriesMeta(event.seriesId);
56.   const past = isPastEvent(event.dateEnd, event.sessions ?? []);
57.   const flag = countryFlag(event.circuit?.countryCode ?? '');
58.   const validSessions = (options.sessions ?? event.sessions ?? []).filter((session) => !isPlaceholderTime(session.startTimeUTC));
59.   const sessionsHtml = renderSessionsHtml(
60.     validSessions,
61.     meta.color,
62.     options.variant === 'calendar-detail' ? 'text-zinc-400' : 'text-zinc-500',
63.   );
64. 
65.   if (options.variant === 'calendar-detail') {
66.     const spanLabel = renderCalendarSpanLabel(event, options.dateStr, meta.color);
67. 
