75.         <div class="flex items-center gap-2 mb-1 flex-wrap">
76.           <span class="text-xs font-bold px-2 py-0.5 rounded text-white uppercase tracking-wide" style="background-color:${meta.color}">${escapeHtml(meta.shortLabel)}</span>
77.           <span class="text-[11px] text-zinc-500 font-mono">Rd ${event.round}</span>
78.           ${spanLabel}
79.         </div>
80.         <h3 class="font-bold text-sm ${past ? 'text-zinc-500' : 'text-zinc-100'} mb-1">${escapeHtml(event.eventName)}</h3>
81.         <div class="flex items-center gap-1.5 text-xs text-zinc-500 ${validSessions.length > 0 ? 'mb-2' : ''}">
82.           ${flag ? `<span class="text-sm">${flag}</span>` : ''}<span>${escapeHtml(event.circuit?.name ?? '')}</span>
83.         </div>
84.         ${validSessions.length > 0 ? `<div class="flex flex-wrap gap-x-3 gap-y-1">${sessionsHtml}</div>` : ''}
85.       </div>
86.     </article>`;
